import{_ as p,a0 as l,w as s,s as n,I as r,x as e,a1 as T,A as a,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"初識 HTTP/2（一） | LCTT x X-CMD","titleTemplate":false,"description":"初識 HTTP/2（一） | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初識 HTTP/2（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初識 HTTP/2（一） | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20160823 Getting Started with HTTP2 - Part 1","title":"初識 HTTP/2（一）","tag":"201701","desc":""},"relativePath":"201701/20160823 Getting Started with HTTP2 - Part 1.md","filePath":"[post].md"}'),d={name:"201701/20160823 Getting Started with HTTP2 - Part 1.md"};function m(P,t,H,u,g,f){const i=l("Link");return s(),n("div",null,[t[22]||(t[22]=r("h1",{id:"初識-http-2-一",tabindex:"-1"},[e("初識 HTTP/2（一） "),r("a",{class:"header-anchor",href:"#初識-http-2-一","aria-label":"Permalink to “初識 HTTP/2（一）”"},"​")],-1)),t[23]||(t[23]=r("p",null,[r("img",{src:"https://static.viget.com/_284x284_crop_center-center/http2-pizza.png?mtime=20160822160641",alt:""})],-1)),t[24]||(t[24]=r("blockquote",null,[r("p",null,"用披薩來説明當你訂單數很大的時候 HTTP/2 是怎麼打敗 HTTP/1.1 的。")],-1)),r("p",null,[t[1]||(t[1]=e("在建立網站和應用的方式上 HTTP/2 有些令人驚歎的改變，在 HTTP/2 發佈後的一年半，幾乎 ",-1)),T(i,{href:"https://w3techs.com/technologies/details/ce-http2/all/all"},{default:a(()=>[...t[0]||(t[0]=[e("10% 的網站使用了 HTTP/2",-1)])]),_:1}),t[2]||(t[2]=e("。它絕對值得采用，但是這篇文章應該首先推給使用 HTTP/2 的前端開發者。這個連載的文章是指導前端開發者怎麼轉換到 HTTP/2。",-1))]),t[25]||(t[25]=o('<p>本文涵蓋了 HTTP/2 對 HTTP/1.1 來説有什麼提高的內容，並且向前端開發者介紹了 HTTP/2。</p><h3 id="再次讓我想起什麼是-http" tabindex="-1">再次讓我想起什麼是 HTTP ... <a class="header-anchor" href="#再次讓我想起什麼是-http" aria-label="Permalink to “再次讓我想起什麼是 HTTP ...”">​</a></h3><p>超文本傳輸協議，也就是 HTTP，這個協議決定了 web 內容怎麼傳輸。HTTP/1.1 在 1999 年被標準化，那時候的 web 和現在有很大的不同，表格霸佔了整個網絡。樣式通常被內聯在元素中，如果網站管理員更加的細緻，他們會在頭部寫個 <code>&lt;style&gt;</code>標籤。 JavaScript 也被丟在文檔裏面，那時候完整的網站通常也不會超過幾頁。</p><p>HTTP/1.1 預計這種情況會持續一段時間，所以它並沒有太過關注在讓一個站點可以加載大量的資源方面，因為那時候的開發者並不需要這個。因此它使用了一個非常簡單的方式來處理資源，你訪問一個資源然後服務器去尋找它，並且返回你訪問的資源，或者告訴你這個資源不存在。這種被叫作&quot;線頭堵塞&quot;方式非常高效，但是當你需要多個資源的時候，這個進程會依次尋找每個資源。這意味着在你訪問第二個資源之前，服務器必須找到你訪問的第一個資源並且載入它，或者告訴你沒找到。</p><h3 id="大型站點的發展" tabindex="-1">大型站點的發展 <a class="header-anchor" href="#大型站點的發展" aria-label="Permalink to “大型站點的發展”">​</a></h3><p>在 1999 年之後的幾年裏，隨着 php 和其他像 Rails 這樣的動態語言的崛起，站點變得越來越複雜。css 文件也隨着向響應式開發的轉變而變的越來越大，因此像 Sass 這樣的可以創造一個簡單的工作環境的 CSS 編譯器就應運而生。 JavaScript 也在 web 上有了更大的作用，它允許開發者編寫複雜的應用，這曾經只是 C++ 開發人員的工作。隨着 Retina 和高清顯示屏的興起，也讓圖片變得更高清。隨着這些改變，文件大小呈現指數式的增長，使得本來是等待幾個字節的資源變成了加載幾千字節，甚至在某些情況下有幾兆。當你開始載入頁面的其它東西前，必須先載入數百 K 的東西，你只能樂觀的假設你的用户有很快的網絡接入。</p><p>想像 HTTP/1.1 是個過去的那種櫃枱購買式的街旁披薩店。你能自己過去並且預定一個雪碧和 2 片 Angry Hawaiian ，然後等待 3 分鐘。他們可以很容易地處理這些，實際上這是一個蓬勃發展的商業模式-定單簡單、處理迅速。</p><p><img src="https://static.viget.com/_300xAUTO_crop_center-center/http2-pizzaorder1.png?mtime=20160823122331" alt=""></p><p>然而，一旦你決定在同樣的披薩店主辦一場小區域的季度頒獎典禮，事情就變的更復雜了。每個人都預定不同的東西，快速而雜亂無章讓等待時間直線上升。</p><p><img src="https://static.viget.com/_300xAUTO_crop_center-center/http2-pizzaorder2.png?mtime=20160823130750" alt=""></p><h3 id="哪裏是-http-2-的舞台" tabindex="-1">哪裏是 HTTP/2 的舞台 <a class="header-anchor" href="#哪裏是-http-2-的舞台" aria-label="Permalink to “哪裏是 HTTP/2 的舞台”">​</a></h3><p>HTTP/2 對前端開發者主要的承諾就是複用。意思就是資源請求能發生在同一時間，並且服務器能馬上響應這些資源。在請求之間沒有等待，因為它們發生在同一時間。</p><p>使用同樣的比喻，HTTP/2 允許披薩店在餐館他們自己區域舉辦派對。派一個服務員接受訂單，並把所有已經準備好的訂單交付。當其他人的比薩在製作的時候，你也不需要花 30 分鐘去等待你的雪碧，它們在第一批交付的東西之中。這方式使得管理大量訂單更加簡單，並且防止人們等他們的訂單時間太長。</p><p>複用帶給我們的 web 開發的大變化是改變了文件的加載方式。幫助繞過資源加載的 HTTP/1.1 瓶頸的方式是通過連接和壓縮需要被加載的文件。所有任務運行器都默認採取這樣的操作方式，或者需要作一點小設置就行。和過去一樣，開發人員可以將圖像放在精靈拼圖（sprite sheets）中，這會減少了對服務器的請求數。</p><h3 id="改進-http-1-1" tabindex="-1">改進 HTTP/1.1 <a class="header-anchor" href="#改進-http-1-1" aria-label="Permalink to “改進 HTTP/1.1”">​</a></h3>',15)),r("p",null,[t[4]||(t[4]=e("將文件連接起來是個處理 HTTP1.1 的請求限制問題的非常聰明的方式，但是連接文件的主要問題是它要求用户第一次訪問整個網站時下載所有的資源。一旦它們載入後，瀏覽器就會緩存所有的資源。這能提高用户每次訪問網頁時的速度，但是前期負載很重，對",-1)),T(i,{href:"https://blog.kissmetrics.com/speed-is-a-killer/"},{default:a(()=>[...t[3]||(t[3]=[e("跳出率不利",-1)])]),_:1}),t[5]||(t[5]=e("。此外，他們可能為所不訪問的頁面加載資源。期望用户訪問每個頁面以查看每個樣式，並與每個腳本進行交互是不現實的。此外，在加拿大和歐洲以及幾乎每個美國移動提供商的地方，有每月的帶寬上限。不是加載額外的 54 千字節的內容就會超過每月的流量限制，而是讓我們假設用户想保留這些額外的流量看 Taylor Swift 的 gif。",-1))]),t[26]||(t[26]=r("p",null,"使用 HTTP/2 和多路複用，您可以開發一些最高效的網站，但它需要一些重新思考、甚至​​撤銷之前的最佳做法。重複一次，我的目的是加快 HTTP/2 的會話，使用我們新的工具，我們可以發現這些新的最佳的做法。",-1)),r("p",null,[t[7]||(t[7]=e("在我的下一篇文章，",-1)),T(i,{href:"https://www.viget.com/articles/getting-started-with-http-2-part-2"},{default:a(()=>[...t[6]||(t[6]=[e("我將探索建設基於 HTTP/2 的網站的一些最好方式",-1)])]),_:1}),t[8]||(t[8]=e("。",-1))]),t[27]||(t[27]=r("hr",null,null,-1)),r("p",null,[t[10]||(t[10]=e("via: ",-1)),T(i,{href:"https://www.viget.com/articles/getting-started-with-http-2-part-1?imm_mid=0eb24a&cmp=em-web-na-na-newsltr_20161130"},{default:a(()=>[...t[9]||(t[9]=[e("https://www.viget.com/articles/getting-started-with-http-2-part-1?imm_mid=0eb24a&cmp=em-web-na-na-newsltr_20161130",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=e("作者：",-1)),T(i,{href:"https://www.viget.com/about/team/btinsley"},{default:a(()=>[...t[11]||(t[11]=[e("Ben",-1)])]),_:1}),t[15]||(t[15]=e(" 譯者：",-1)),T(i,{href:"https://github.com/hkurj"},{default:a(()=>[...t[12]||(t[12]=[e("hkurj",-1)])]),_:1}),t[16]||(t[16]=e(" 校對：",-1)),T(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[19]||(t[19]=e("本文由 ",-1)),T(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[17]||(t[17]=[e("LCTT",-1)])]),_:1}),t[20]||(t[20]=e(" 組織編譯，",-1)),T(i,{href:"https://linux.cn/"},{default:a(()=>[...t[18]||(t[18]=[e("Linux中國",-1)])]),_:1}),t[21]||(t[21]=e(" 榮譽推出",-1))])])}const x=p(d,[["render",m]]);export{b as __pageData,x as default};
